export default function FoundationSettings() {
  const [rows, setRows] = useState([]);
  const [values, setValues] = useState({});
  const [original, setOriginal] = useState({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const settingsSaveRef = useRef(false);

  useEffect(() => {
    const load = async () => {
      try {
        const all = await loadAllEntityRows({ entity: SettingsEntity, sort: null, label: "Foundation Settings catalog" });
        const relevant = (all || []).filter((row) => ACTIVE_KEYS.has(row.setting_name));
        const map = Object.fromEntries(relevant.map((row) => [row.setting_name, row.setting_value ?? ""]));
        setRows(relevant);
        setValues(map);
        setOriginal(map);
      } catch (e) {
        setError(e.message || "Could not load Foundation settings.");
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  const patch = (key, value) => setValues((prev) => ({ ...prev, [key]: String(value) }));
  const dirtyCount = rows.filter((row) => String(values[row.setting_name] ?? "") !== String(original[row.setting_name] ?? "")).length;

  // #83 — stage every managed key back to the calculator's documented fallback.
  const handleResetDefaults = () => {
    setValues((prev) => resetValuesToDefaults(prev, FOUNDATION_SETTINGS_DEFAULTS, [...ACTIVE_KEYS]));
    setMessage("Defaults staged — click Save to persist them.");
  };

  const save = async () => {
    if (settingsSaveRef.current) return;
    settingsSaveRef.current = true;
    setSaving(true);
    setError("");
    setMessage("");
    try {
      const result = await saveSettingsRowsSafely({
        SettingsEntity,
        rows,
        values,
        originalValues: original,
      });
      setRows(result.rows);
      setOriginal(result.snapshot);
      setMessage(result.changedCount ? `Saved ${result.changedCount} Foundation setting${result.changedCount === 1 ? "" : "s"}.` : "No Foundation settings changed.");
    } catch (e) {
      setError(e.message || "Could not save Foundation settings. Admin permission may be required.");
    } finally {
      settingsSaveRef.current = false;
      setSaving(false);
    }
  };

  if (loading) return <div className="p-10 text-center text-gray-400">Loading Foundation settings…</div>;

  return (
    <div className="min-h-full bg-gray-50">
      <div className="max-w-[1050px] mx-auto p-4 sm:p-5 space-y-4">
